      return "UNEXPECTED_SYNTAX";
    case ErrorCode::InvalidNumberLiteral:
      return "INVALID_NUMBER_LITERAL";
    case ErrorCode::InvalidUnicodeLiteral:
      return "INVALID_UNICODE_LITERAL";
    case ErrorCode::UndefinedVariable:
      return "UNDEFINED_VARIABLE";
    case ErrorCode::NoVariablesInScope:
      return "NO_VARIABLES_IN_SCOPE";
    case ErrorCode::NestedAggregation:
      return "NESTED_AGGREGATION";
    case ErrorCode::UnknownFunction:
